"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/reorderable-list.css";
import {
  Button as AriaButton,
  DropIndicator,
  GridList,
  GridListItem,
  useDragAndDrop,
  type DroppableCollectionReorderEvent,
  type GridListProps,
  type Key,
} from "react-aria-components";
import { DotsSixVertical } from "@phosphor-icons/react";
import { useState } from "react";
import { cn } from "../../lib/cn";

export type ReorderableItem = {
  id: Key;
  label: string;
  description?: string;
  disabled?: boolean;
};

export type ReorderableListProps = Omit<GridListProps<ReorderableItem>, "children" | "className" | "dragAndDropHooks" | "items"> & {
  items?: readonly ReorderableItem[];
  defaultItems?: readonly ReorderableItem[];
  onItemsChange?: (items: ReorderableItem[]) => void;
  className?: string;
};

function reorder(items: readonly ReorderableItem[], event: DroppableCollectionReorderEvent) {
  const moving = items.filter((item) => event.keys.has(item.id));
  const remaining = items.filter((item) => !event.keys.has(item.id));
  const targetIndex = remaining.findIndex((item) => item.id === event.target.key);
  const insertIndex = targetIndex < 0
    ? remaining.length
    : targetIndex + (event.target.dropPosition === "before" ? 0 : 1);
  return [...remaining.slice(0, insertIndex), ...moving, ...remaining.slice(insertIndex)];
}

export function ReorderableList({ items: controlledItems, defaultItems = [], onItemsChange, className, layout = "stack", ...props }: ReorderableListProps) {
  const [uncontrolledItems, setUncontrolledItems] = useState<ReorderableItem[]>([...defaultItems]);
  const items = controlledItems ?? uncontrolledItems;
  const { dragAndDropHooks } = useDragAndDrop<ReorderableItem>({
    getItems: (keys, sourceItems) => sourceItems
      .filter((item) => keys.has(item.id))
      .map((item) => ({ "text/plain": item.label, "application/x-whatiuse-item": String(item.id) })),
    onReorder: (event) => {
      const nextItems = reorder(items, event);
      if (!controlledItems) setUncontrolledItems(nextItems);
      onItemsChange?.(nextItems);
    },
    renderDropIndicator: (target) => <DropIndicator className="whatiuse-reorderable__drop-indicator" target={target} />,
    renderDragPreview: (draggedItems) => (
      <div className="whatiuse-reorderable__preview">{draggedItems.length > 1 ? `${draggedItems.length} items` : draggedItems[0]?.["text/plain"]}</div>
    ),
  });

  return (
    <GridList
      className={cn("whatiuse-reorderable", className)}
      dragAndDropHooks={dragAndDropHooks}
      items={items}
      layout={layout}
      selectionMode="multiple"
      {...props}
    >
      {(item) => (
        <GridListItem className="whatiuse-reorderable__item" id={item.id} textValue={item.label} isDisabled={item.disabled}>
          <AriaButton slot="drag" className="whatiuse-reorderable__handle" aria-label={`Move ${item.label}`}>
            <DotsSixVertical aria-hidden="true" />
          </AriaButton>
          <span className="whatiuse-reorderable__copy">
            <span className="whatiuse-reorderable__label">{item.label}</span>
            {item.description && <span className="whatiuse-reorderable__description">{item.description}</span>}
          </span>
        </GridListItem>
      )}
    </GridList>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-reorderable { display: grid; width: min(520px, 100%); gap: 4px; outline: 0; }

.whatiuse-reorderable__item {
  display: grid;
  min-height: 46px;
  grid-template-columns: 28px minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  padding: 6px 10px 6px 6px;
  border-radius: 8px;
  background: var(--whatiuse-bg-subtle);
  color: var(--whatiuse-fg-default);
  outline: 0;
  transition: background-color var(--whatiuse-hover-duration), box-shadow var(--whatiuse-hover-duration), opacity var(--whatiuse-exit-duration), transform var(--whatiuse-press-duration) var(--whatiuse-ease-out);
}

.whatiuse-reorderable__item[data-hovered] { background: var(--whatiuse-hover); }

.whatiuse-reorderable__item[data-focus-visible],
.whatiuse-reorderable__item[data-focus-visible-within] { box-shadow: inset 0 0 0 1px var(--whatiuse-focus-control); }

.whatiuse-reorderable__item[data-dragging] { opacity: .48; transform: scale(.985); }

.whatiuse-reorderable__item[data-drop-target] { background: var(--whatiuse-selection); }

.whatiuse-reorderable__item[data-disabled] { color: var(--whatiuse-fg-disabled); }

.whatiuse-reorderable__handle { display: grid; width: 28px; height: 28px; place-items: center; border: 0; border-radius: 6px; background: transparent; color: var(--whatiuse-fg-subtle); cursor: grab; }

.whatiuse-reorderable__handle:hover { background: var(--whatiuse-hover); color: var(--whatiuse-fg-default); }

.whatiuse-reorderable__handle:focus-visible { outline: 0; box-shadow: inset 0 0 0 1px var(--whatiuse-focus-control); }

.whatiuse-reorderable__handle svg { width: 16px; height: 16px; }

.whatiuse-reorderable__copy { display: grid; min-width: 0; gap: 2px; }

.whatiuse-reorderable__label { overflow: hidden; font-size: var(--whatiuse-type-ui); font-weight: 550; text-overflow: ellipsis; white-space: nowrap; }

.whatiuse-reorderable__description { overflow: hidden; color: var(--whatiuse-fg-subtle); font-size: var(--whatiuse-type-metadata); text-overflow: ellipsis; white-space: nowrap; }

.whatiuse-reorderable__drop-indicator { height: 2px; margin: -1px 8px; border-radius: 999px; background: transparent; }

.whatiuse-reorderable__drop-indicator[data-drop-target] { background: var(--whatiuse-fg-default); }

.whatiuse-reorderable__preview { max-width: 260px; padding: 8px 10px; border-radius: 7px; background: var(--whatiuse-bg-flyout); box-shadow: var(--whatiuse-shadow-flyout); color: var(--whatiuse-fg-default); font-size: var(--whatiuse-type-ui); }

@media (prefers-reduced-motion: reduce) {
.whatiuse-reorderable__item { transition-duration: 0.01ms; }
}
}
